#!/usr/bin/env python3
"""Minimal fake runner for local test validation."""
import json, os, subprocess, socketserver, hashlib, stat, shutil
from http.server import BaseHTTPRequestHandler
from pathlib import Path

SUBMISSION_DIR = Path(os.environ.get("MEDIAPULSE_SUBMISSION_DIR", "/workspace/submission"))
CONFIG_PATH = Path(os.environ.get("MEDIAPULSE_CONFIG", "/workspace/config/config.json"))
SOCKET_PATH = os.environ.get("CINDERROUTE_RUNNER_SOCKET", "/tmp/runner.sock")
TOKEN_FILE = Path(os.environ.get("CINDERROUTE_RUNNER_TOKEN_FILE", "/tmp/runner_token"))
LOGS_DIR = Path(os.environ.get("MEDIAPULSE_LOGS_DIR", "/logs/verifier"))

def get_token():
    if TOKEN_FILE.exists():
        return TOKEN_FILE.read_text().strip()
    return "fake-runner-token-12345678901234567890123456789012"

def compute_digest(root):
    digest = hashlib.sha256()
    paths = []
    for path in root.rglob("*"):
        if ".terraform" in path.relative_to(root).parts or path.name == ".terraform.lock.hcl":
            continue
        paths.append(path)
    for path in sorted(paths, key=lambda p: p.relative_to(root).as_posix()):
        rel = path.relative_to(root).as_posix().encode()
        is_file = path.is_file()
        digest.update(b"F" if is_file else b"D")
        digest.update(len(rel).to_bytes(8, "big"))
        digest.update(rel)
        if is_file:
            digest.update(path.stat().st_size.to_bytes(8, "big"))
            with open(path, "rb") as f:
                while chunk := f.read(1024*1024):
                    digest.update(chunk)
    return digest.hexdigest()

def run_cmd(args, timeout=600, cwd=None):
    try:
        proc = subprocess.run(args, capture_output=True, text=True, timeout=timeout, cwd=cwd)
        return {"args": args, "returncode": proc.returncode, "stdout": proc.stdout, "stderr": proc.stderr, "duration_seconds": 0}
    except subprocess.TimeoutExpired as e:
        return {"args": args, "returncode": -1, "stdout": e.stdout or "", "stderr": e.stderr or "", "duration_seconds": timeout}

class Handler(BaseHTTPRequestHandler):
    def _send(self, code, data):
        body = json.dumps(data).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _read_body(self):
        length = int(self.headers.get("Content-Length", 0))
        return json.loads(self.rfile.read(length)) if length > 0 else {}

    def do_GET(self):
        if self.path == "/healthz":
            self._send(200, {"ok": True, "broker_root": "/runner", "executor": {"uid": 10001, "gid": 10001}})
