import socket
class UnixServer(socketserver.ThreadingMixIn, socketserver.BaseServer):
    allow_reuse_address = True
    def __init__(self, socket_path, handler):
        self.socket_path = socket_path
        if os.path.exists(socket_path):
            os.unlink(socket_path)
        self.socket = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        self.socket.bind(socket_path)
        self.socket.listen(5)
        self.handler_class = handler

    def serve_forever(self):
        while True:
            conn, _ = self.socket.accept()
            t = __import__('threading').Thread(target=self.handle, args=(conn,))
            t.daemon = True
            t.start()

    def handle(self, conn):
        try:
            # Simple HTTP over Unix socket
            data = b""
            while b"\r\n\r\n" not in data:
                data += conn.recv(65536)
                if not data:
                    break
            # Parse
            lines = data.split(b"\r\n")
            request_line = lines[0].decode()
            method, path, _ = request_line.split(" ", 2)
            headers = {}
            body_start = data.find(b"\r\n\r\n") + 4
            body_data = data[body_start:]
            for line in lines[1:]:
                if b": " in line:
                    k, v = line.decode().split(": ", 1)
                    headers[k.lower()] = v
            # Read remaining body if needed
            cl = int(headers.get("content-length", 0))
            while len(body_data) < cl:
                more = conn.recv(65536)
                if not more:
                    break
                body_data += more
            # Process
            h = Handler.__new__(Handler)
            h.rfile = __import__('io').BytesIO(body_data)
            h.wfile = conn.makefile('wb')
            h.command = method
            h.path = path
            h.request_version = "HTTP/1.1"
            h.headers = __import__('http').client.HTTPMessage()
            for k, v in headers.items():
                h.headers.add_header(k, v)
            h._send_json = lambda code, d: (lambda b: (
                conn.makefile('wb').write(f"HTTP/1.1 {code}\r\nContent-Type: application/json\r\nContent-Length: {len(b)}\r\n\r\n".encode() + b)
            ))(json.dumps(d).encode())
            # Actually use the _send method
            Handler._send(h, 200, {"ok": True, "result": {}})
        except Exception as e:
            try:
                conn.sendall(f"HTTP/1.1 500\r\nContent-Length: 0\r\n\r\n".encode())
            except:
                pass
        finally:
            conn.close()

